UIScoreExplosionFragmentSprite=function(game){var randomFragmentIndex=Math.floor(Math.random()*9);Phaser.Sprite.call(this,game,0,0,'playerpanel','fragment'+randomFragmentIndex);this.game.physics.p2.enable(this);this.body.allowSleep=false;this.body.onBeginContact.add(this._hitSomething,this);this.body.clearShapes();this.body.loadPolygon('playerpanel-physics','fragment'+randomFragmentIndex);this.body.setMaterial(UIUtils.scoreFragmentMaterial);this.body.setCollisionGroup(UIUtils.scoreFragmentCollisionGroup);this.body.collides([UIUtils.playerPanelFloorCollisionGroup]);this.body.collideWorldBounds=false;this.kill();};UIScoreExplosionFragmentSprite.prototype=Object.create(Phaser.Sprite.prototype);UIScoreExplosionFragmentSprite.prototype.constructor=UIScoreExplosionFragmentSprite;UIScoreExplosionFragmentSprite.prototype.update=function(){if(!this.exists){return;}if(this.fading){this.alpha=Math.max(0.0,this.alpha-0.025);}if(this.alpha==0.0){this.kill();}};UIScoreExplosionFragmentSprite.prototype.spawn=function(x,y,width){var speed=UIConstants.SCORE_FRAGMENT_MIN_SPEED+Math.random()*(UIConstants.SCORE_FRAGMENT_MAX_SPEED-UIConstants.SCORE_FRAGMENT_MIN_SPEED);var direction=UIConstants.SCORE_FRAGMENT_MIN_ANGLE+Math.random()*(UIConstants.SCORE_FRAGMENT_MAX_ANGLE-UIConstants.SCORE_FRAGMENT_MIN_ANGLE);var speedX=Math.cos(direction)*speed;var speedY=Math.sin(direction)*speed;x+=width*Math.random()-width/2;y+=speedY*0.1;this.reset(x,y);this.alpha=1.0;this.body.rotation=Math.random()*Math.PI*2.0;this.body.velocity.x=speedX;this.body.velocity.y=speedY;this.body.angularVelocity=Math.random()*UIConstants.SCORE_FRAGMENT_MAX_ROTATION_SPEED-UIConstants.SCORE_FRAGMENT_MAX_ROTATION_SPEED/2.0;this.fading=false;};UIScoreExplosionFragmentSprite.prototype.retire=function(){this.kill();};UIScoreExplosionFragmentSprite.prototype._hitSomething=function(body,shapeA,shapeB,equation){this.fading=true;};